{
  "thesis": "八家公司的可见差异，不在于是否拥有预训练、后训练等通用环节，而在于如何把数据质量、训练系统、评测约束和产品反馈连接起来：OpenAI突出可验证的编程任务交付，Anthropic突出人类反馈平台与分层发布治理，Google DeepMind突出多模态训练和成本分层，DeepSeek突出算法—系统协同，Moonshot Kimi突出环境与轨迹生产，MiniMax突出长推理的训练效率与奖励校准，ByteDance Seed突出真实业务分布牵引评测，Tencent Hunyuan突出组织重建后跨产品反馈驱动后训练。建议以“长期平台支撑模型节点项目”为组织解释，以checkpoint、数据和评测版本为交接对象，以模型、环境及系统配置束为Agent交付单位；这些是综合推论，不是八家公司均已公开的组织制度。有效管线的建议验收结果是可复现、可验证、可回滚、可沉淀。",
  "claims": [
    {
      "claim": "OpenAI的codex-1把真实软件工程任务、执行环境和可验证交付共同纳入后训练：通过RL学习修改代码、运行测试，并以文件、终端日志和diff支持用户复核。",
      "source": ["codex-card"],
      "locator": "第1页；第5页User transparency and diff reviews",
      "qualification": "限定于2025年5月Codex节点；不能据此补写OpenAI整体预训练、中训、标注供应商或团队汇报线。"
    },
    {
      "claim": "Codex针对虚假完成声明使用环境扰动和合成环境，在RL中惩罚声明与行为不一致；产品反馈随后推动网络权限由默认隔离向按项目配置演进。",
      "source": ["codex-card"],
      "locator": "第5—6页§2.3；第8页§2.6 June 3, 2025 Update",
      "qualification": "初始执行阶段无网络与6月3日可选联网须分开叙述；合成测试改善不代表实际任务总体成功率。"
    },
    {
      "claim": "Anthropic的Claude 4数据覆盖公开网络、第三方非公开数据、标注服务和承包商、自愿授权用户数据及内部生成数据；人工工作包括偏好选择、安全评测和对抗测试。",
      "source": ["claude-4"],
      "locator": "第3页§1.1.1；第4页§1.1.3",
      "qualification": "能确认数据来源类别与工作类型，不能确认各类占比、采购规模或承包商管理汇报线。"
    },
    {
      "claim": "Anthropic公开的RL Data Platform职责连接研究需求、专家界面、结构化反馈和训练数据混合，平台工程与RL研究之间存在明确的工作接口。",
      "source": ["anthropic-rl-jobs"],
      "locator": "About the role；Key responsibilities；Representative projects",
      "qualification": "招聘描述证明职责设计和能力需求，不证明所有代表项目已经上线；岗位内容不能倒推为2025年Claude 4时已具备同样的平台规模或交付时效。"
    },
    {
      "claim": "Claude 4发布治理区分能力评测、独立内部质询和安全等级决策：Frontier Red Team形成报告，Alignment Stress Testing团队审阅，Responsible Scaling Officer与CEO确定所需ASL标准。",
      "source": ["claude-4"],
      "locator": "第5—7页§1.2",
      "qualification": "董事会与Long-Term Benefit Trust参与监督，不等同于技术团队日常汇报线；Opus 4采用ASL-3是预防性判断，并非已经确认越过相关能力阈值。"
    },
    {
      "claim": "Google DeepMind在Gemini 2.5节点将多模态数据、代码数据扩展、SFT/RM/RL质量控制、TPUv5p与Pathways容错，以及小模型蒸馏连接为能力—成本分层管线。",
      "source": ["gemini-25"],
      "locator": "§2.1—2.4；§2.6 Code",
      "qualification": "技术协同可确认，团队边界、资源审批权和正式交接制度未公开；不把技术一体化直接等同于组织集中化。"
    },
    {
      "claim": "Gemini 2.5的预览到稳定版路径结合用户反馈，Pro与Flash于2025年6月17日进入稳定可用阶段，Flash-Lite同时进入预览；思考预算与模型分层把Serving成本约束前移至模型设计。",
      "source": ["gemini-launch", "gemini-25"],
      "locator": "发布正文；技术报告§2.5、§2.7",
      "qualification": "成本约束前移属于机制解释；反馈进入具体训练批次、发布门槛与责任人尚不可确认。"
    },
    {
      "claim": "DeepSeek-V3的可见训练序列为14.8T token预训练、4K至32K再至128K上下文扩展、SFT与RL；数学和代码比重、去冗余和FIM策略在预训练阶段已有针对性设计。",
      "source": ["deepseek-v3"],
      "locator": "§4.1—4.3；§5",
      "qualification": "将上下文扩展作为中训功能的比较对象，不宣称公司设有独立中训部门。"
    },
    {
      "claim": "DeepSeek-V3后训练按领域分工生产数据：推理领域借助内部R1及专家模型生成、筛选；非推理领域使用V2.5生成并由人工核验；规则奖励与模型奖励并用。",
      "source": ["deepseek-v3"],
      "locator": "§5.1；§5.2.1；附录A",
      "qualification": "附录区分研究工程、数据标注与商业合规贡献，但不能由作者名单推断团队规模、雇佣关系或决策权。"
    },
    {
      "claim": "DeepSeek将FP8、DualPipe、通信内核和模型结构协同优化，并在Serving中分离prefill与decode，使用在线专家负载统计调整部署。",
      "source": ["deepseek-v3", "deepseek-release"],
      "locator": "§3.1—3.2、§3.4；发布说明§6",
      "qualification": "线上负载反馈是系统优化闭环，不等同于用户内容回流训练；公开训练成本不含前期研究和消融实验。"
    },
    {
      "claim": "Moonshot Kimi在K2节点同时建设预训练改写增强和Agent轨迹生产：知识改写包含保真校验，工具规格、任务rubric、状态模拟与真实代码沙箱共同生成后训练数据。",
      "source": ["kimi-k2"],
      "locator": "§2.2；§3.1—3.1.1",
      "qualification": "真实工具规格不代表真实工具已被逐一执行；模拟轨迹有保真度限制，论文明确以真实沙箱补充。"
    },
    {
      "claim": "Kimi K2的RL使用可验证奖励与自评rubric，数据团队参与复杂指令和评分标准制作；Kubernetes沙箱、独立环境服务、并发rollout和partial rollout共同支撑长任务训练。",
      "source": ["kimi-k2"],
      "locator": "§3.2.1—3.2.2；§3.3",
      "qualification": "训练与推理引擎协作机制可确认，组织归属不可确认；公开API和权重不证明已有产品反馈自动回训机制。"
    },
    {
      "claim": "MiniMax-M1从Text-01继续预训练7.5T token，强化天然QA、STEM与代码数据，再经长上下文扩展、长CoT SFT和分课程RL；合成数据政策随阶段而异。",
      "source": ["minimax-m1"],
      "locator": "§2；§4.1；§4.3；§5",
      "qualification": "持续预训练避免合成数据，不代表全流程不用合成数据；逻辑任务使用合成数据，80K扩展阶段又降低部分合成推理数据权重。"
    },
    {
      "claim": "MiniMax-M1把训练与推理数值一致性、奖励模型偏差和长输出稳定性作为同一RL工程问题处理；人工盲评用于校准GenRM，在线长度偏差触发再校准。",
      "source": ["minimax-m1"],
      "locator": "§3.2；§4.2；§5",
      "qualification": "这是训练内部闭环，不可替代消费产品反馈证据；约53.47万美元仅为所述RL训练租赁成本，不是完整模型研发成本。"
    },
    {
      "claim": "ByteDance Seed的研究边界从2025年2月负责人调整后开始。第一财经援引知情人士称吴永辉偏基础研究、朱文佳偏模型应用，两者均在Seed并向梁汝波汇报。",
      "source": ["yicai"],
      "locator": "2025年2月21日正文",
      "qualification": "属于媒体援引知情人士的说法；具体团队转隶与朱文佳职务变化未获字节回应，不向后续所有模型节点无条件外推。"
    },
    {
      "claim": "Seed2.0用经授权的业务使用分布和开发者轨迹识别需求，再以长尾知识、复杂指令、前后端任务和端到端交付评测牵引研发；Pro/Lite/Mini承接不同成本与时延需求。",
      "source": ["seed-2", "seed-launch"],
      "locator": "模型卡§1—2、§3.1.1、§3.3—3.4；模型目录Seed2.0条目",
      "qualification": "以2026年2月Seed2.0为技术主节点；授权使用统计不等于全部原始数据进入训练。预训练配方、标注组织、中训与训练Infra仍未知。Seed2.1仅能确认后续发布节点。"
    },
    {
      "claim": "Tencent Hunyuan的研究边界从2025年12月17日调整开始：财新报道新设AI Infra、AI Data与数据计算平台部门，并披露姚顺雨两个角色对应的不同汇报关系。",
      "source": ["caixin"],
      "locator": "2025年12月18日正文首段",
      "qualification": "首席AI科学家向刘炽平汇报；兼任AI Infra和大语言模型部门负责人时向卢山汇报。不能把AI Data或数据计算平台负责人及其汇报线补写为姚顺雨。"
    },
    {
      "claim": "腾讯公开的后续节点为2026年1月下旬基础设施重建、4月23日Hy3 Preview、7月6日Hy3正式发布；来自50多个产品的反馈关联更高质量后训练数据、扩大的RL及工具格式、多轮意图和幻觉修正。",
      "source": ["tencent-launch", "hy3"],
      "locator": "发布正文首段及末段；仓库Model Introduction、More Reliable Product Experiences",
      "qualification": "属于官方对迭代路径和效果的陈述，不能将改善因果完全归于领导调整；未披露反馈筛选、隐私授权与批次交接的内部细节。"
    },
    {
      "claim": "Hy3发布不仅包括模型权重和API，还提供工具及推理解析、MTP、量化与部署配方；其公开RL适配支持verl、Megatron-LM和vLLM rollout。",
      "source": ["hy3", "tencent-launch"],
      "locator": "Deployment、RL Post-training、Quantization；发布正文",
      "qualification": "外部可用训练配方不证明Hy3内部训练使用同一完整栈；产品接入和部署指南不能补齐预训练或中训过程。"
    },
    {
      "claim": "Harness改变了能力归因和交付边界：任务分数取决于工具、环境、尝试次数、筛选器与预算；Coding Agent交付需包含可执行改动、测试证据和权限配置，而非只有文本答案。",
      "source": ["codex-card", "claude-launch", "kimi-release", "minimax-release", "seed-2", "hy3"],
      "locator": "Codex第1、5页；Claude发布附录；Kimi评测脚注；MiniMax SWE-bench methodology；Seed§3.3；Hy3可靠性段落",
      "qualification": "前后对比是任务形态的分析对照，不声称各公司存在统一历史切换点；八家公司不存在可直接横比的同条件Agent成绩。"
    },
    {
      "claim": "建议把长期平台与模型节点项目连接，以checkpoint、数据版本和评测版本交接预训练、中训、后训练；发布时再绑定Serving配置、环境、权限与回归结果。",
      "source": ["anthropic-rl-jobs", "deepseek-v3", "kimi-k2", "gemini-25", "codex-card", "hy3"],
      "locator": "跨来源机制综合，非单一事实段落",
      "qualification": "明确标为组织设计推论与建议，不把版本签收、项目制、回滚权限或四项验收结果写成八家公司已经实行的共同制度。"
    }
  ],
  "counterevidence": [
    {
      "point": "技术管线公开程度与组织公开程度不一致。",
      "evidence": "DeepSeek、Kimi、MiniMax论文详述技术过程，但作者名单不能证明部门结构；OpenAI的Codex文档只覆盖特定产品节点。",
      "implication": "表格区分已公开机制和未知责任边界，不按披露篇幅判断组织优劣。"
    },
    {
      "point": "合成数据不是统一最优路线。",
      "evidence": "Kimi增强预训练改写与模拟轨迹；MiniMax持续预训练避免合成数据，并在长输出RL中降低部分合成数据权重。",
      "implication": "比较阶段、验证方式和失效条件，而不是给公司排列合成数据先进程度。"
    },
    {
      "point": "训练系统不存在可直接移植的最佳方案。",
      "evidence": "DeepSeek采用FP8计算和DualPipe；Kimi因模型规模与内存开销选择不同并行方案，并仅在部分激活存储使用FP8。",
      "implication": "强调架构、精度、内存和通信共同约束，避免以单个优化名称替代Infra分析。"
    },
    {
      "point": "奖励上升不一定代表任务能力上升。",
      "evidence": "MiniMax发现GenRM长度偏差；Codex针对虚假完成声明专门训练；Kimi设置hack-check与预算惩罚。",
      "implication": "人工与自动验证需要校准奖励、行为及最终产物之间的一致性。"
    },
    {
      "point": "Agent榜单不能直接充当模型或组织排名。",
      "evidence": "Claude评测覆盖500题，MiniMax为486题；Kimi区分单次和多次尝试；Seed修复环境并排除部分任务；Gemini明确不同scaffolding结果不可直接比较。",
      "implication": "正文不拼接排行榜，比较评测治理和可复现实验条件。"
    },
    {
      "point": "发布渠道和用户反馈入口不证明训练闭环已经形成。",
      "evidence": "DeepSeek、Kimi、MiniMax公开权重和API；腾讯明确产品反馈后的后训练改善；Codex明确反馈改变网络功能。",
      "implication": "区分系统运行反馈、产品设计反馈和训练数据回流，逐家公司限定可确认环节。"
    },
    {
      "point": "社区问题只能提示交付风险，不能证明内部缺陷或已完成修复。",
      "evidence": "DeepSeek issue #994是外部用户对UE8M0支持的疑问，最终由机器人按过期规则关闭。",
      "implication": "仅用于说明权重格式与推理内核兼容性值得验证，不据此判断官方事故率或内部处理流程。"
    },
    {
      "point": "领导调整与后续模型进展的时间相邻不建立因果。",
      "evidence": "字节媒体仅披露高层分工；腾讯虽披露部门调整及后续Hy3迭代，仍缺少资源投入和项目决策的对照信息。",
      "implication": "严格守住两家时间下界，将组织调整与技术节点并列，不宣称人事变化单独导致性能提升。"
    },
    {
      "point": "证据限制与未完成交付义务必须分开。",
      "evidence": "具名续作明确允许内部结构保持未知；当前没有独立终审或接受记录。",
      "implication": "未知汇报线属于可披露事实边界；三部分写作、组装与独立复核仍待执行，不称终稿，不虚构限制已获单独接受。"
    }
  ],
  "parts": [
    {
      "number": 1,
      "headings": ["核心要点", "管线总览", "八家公司对比"],
      "target_nonspace_characters": 1900,
      "writing_plan": "开篇用五条短结论覆盖八家公司差异及五个指定综合结论，明确组织设计推论身份。随后用一段说明数据贯穿阶段、训练与产品反馈形成多个闭环。比较表设八行，列为公司与节点、数据及训练链、Infra与评测、Serving及反馈、组织可知边界；压缩技术术语，保留各家实质差异。字节从2025年2月后写至Seed2.0，腾讯从2025年12月17日后写至Hy3；其他公司采用相应2025年标志节点，避免伪装同一时点横截面。"
    },
    {
      "number": 2,
      "headings": ["数据与标注", "训练、Infra与评测"],
      "target_nonspace_characters": 1950,
      "writing_plan": "优先解释数据需求如何变成样本、轨迹、rubric与奖励：对照Anthropic人工平台、DeepSeek领域生成与核验、Kimi工具环境、MiniMax人工校准及Seed和腾讯业务反馈。再解释预训练到中训功能再到后训练的能力交接，以DeepSeek上下文扩展、Kimi退火和长上下文激活、MiniMax持续预训练为具体案例；不制造统一阶段名称。Infra比较Google跨数据中心容错、DeepSeek协同优化、Kimi资源弹性与rollout、MiniMax数值一致性。评测部分区分能力进展、奖励校准、风险决策和Serving约束，并交代Anthropic已公开决策权与其余公司的未知范围。"
    },
    {
      "number": 3,
      "headings": ["Harness与Coding Agent", "不确定性"],
      "target_nonspace_characters": 1400,
      "writing_plan": "比较静态回答与环境执行任务的数据单位、后训练信号、沙箱基础设施、评测条件、Serving时延和交付物变化。以Codex的diff与日志、Claude Code的IDE和GitHub工作流、Kimi真实沙箱、Seed环境标准化及Hy3跨scaffolding稳定性展开。建议将模型、工具协议、环境镜像、预算、权限和验收结果绑定发布，并用可复现、可验证、可回滚、可沉淀作为组织验收标准。结尾集中界定内部汇报线、数据占比、标注采购、反馈授权、发布签字与回滚权等未解决问题；不补写其他公司的流程，不附术语或资料清单。三个单元合计5250非空白字符，预算已包含标题、Markdown表格及必要的简短归属表述；最终实际字符数和全文复核须在组装后检查。"
    }
  ]
}
